async ({ workspace: { read, edit }, git: { add, commit, push } }) => {
  const c = JSON.parse((await read("/tmp/peakcharts.json", { format: "raw" })).content);
  const doc = await read("docs/research/dotcom-analog.md", { format: "raw" });
  const sec = `## 6. Peak-aligned: SPY's 2026 top vs the 24 Mar 2000 top

*Added after [this comment](https://github.com/cv/pinance/issues/61#issuecomment-6926871851). Daily SPY closes; offsets are trading days from each top. Data: [\`data/spy-peak-aligned-daily.csv\`](data/spy-peak-aligned-daily.csv).*

SPY's 2026 closing high so far was **$779.09 on 6 Oct 2026**, a figure Financial Datasets also confirms. On 16 Nov SPY was at $739.86, **5.0% below** that high. The dot-com top in SPY was **$153.56 on 24 Mar 2000**, the same day as the S&P 500's closing high of 1,527.46.

${c.a}

${c.b}

| | 2000 top | 2026 top |
|---|---:|---:|
| Gain in the 250 trading days before the top | +17.7% | +16.4% |
| Gain in the 500 trading days before the top | +38.6% | +37.2% |
| Change 29 trading days after the top | −6.5% (5 May 2000) | −5.0% (16 Nov 2026) |
| Worst close in those 29 days | −11.4% | −5.9% (5 Nov) |

${c.c}

**What happened after the 2000 top:**

- SPY fell 10% within 15 trading days (14 Apr 2000).
- It then recovered to within 0.7% of the high by 1 Sep 2000.
- It did not close 20% below the high until 12 Mar 2001, almost a year later.
- The low came on 9 Oct 2002, 49.1% below the high and 637 trading days after the top.

**How to read it:**

- The run-ups into the two tops are almost the same size: about +17% over one year and about +38% over two.
- The first weeks after each top are also similar.
- The 2000 top was only confirmed in hindsight, after more than six months that included a near-retest. 6 Oct is a top only if SPY does not make a new high, so this alignment assumes the top is already in.

`;
  const content = doc.content.replace("## Method and sources", sec + "## Method and sources");
  await edit("docs/research/dotcom-analog.md", { revision: doc.revision, changes: [{ kind: "replaceFile", content }] });
  await add(["docs/research/dotcom-analog.md", "docs/research/data/spy-peak-aligned-daily.csv"]);
  const cm = await commit(["-m", "docs(research): align SPY 2026 top with March 2000 top (#61)"]);
  const p = await push(["origin", "HEAD"]);
  return { c: (cm.stdout + cm.stderr).slice(-300), p: (p.stdout + p.stderr).slice(-200), code: [cm.code, p.code] } as PitJsonValue;
}
